Q: Translate my PDF with &quot;puppeteer&quot; in NodeJs A: <p>Node.js example (official API)</p>
<pre><code>const fs = require(&quot;fs&quot;);
const {TranslationServiceClient} = require(&quot;@google-cloud/translate&quot;).v3;

async function translatePdf() {
  const projectId = &quot;YOUR_PROJECT_ID&quot;;
  const location = &quot;us-central1&quot;; // required region for many translation features
  const client = new TranslationServiceClient();

  const inputPdf = fs.readFileSync(&quot;input.pdf&quot;);

  const request = {
    parent: `projects/${projectId}/locations/${location}`,
    sourceLanguageCode: &quot;fr&quot;,
    targetLanguageCode: &quot;en&quot;,
    documentInputConfig: {
      content: inputPdf.toString(&quot;base64&quot;),
      mimeType: &quot;application/pdf&quot;,
    },
    documentOutputConfig: {
      mimeType: &quot;application/pdf&quot;,
    },
  };

  const [response] = await client.translateDocument(request);

  // API returns translated bytes in base64
  const outputBase64 = response.documentTranslation.byteStreamOutputs?.[0];
  if (!outputBase64) throw new Error(&quot;No translated PDF returned.&quot;);

  fs.writeFileSync(&quot;translated.pdf&quot;, Buffer.from(outputBase64, &quot;base64&quot;));
  console.log(&quot;Translated PDF saved to translated.pdf&quot;);
}

translatePdf().catch(console.error);
</code></pre>
